import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易口诀义 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易口诀义 - 40、【解】 坎下震上"},"headers":[],"relativePath":"zh/classics/koujueyi/042.md","filePath":"zh/classics/koujueyi/042.md"}'),r={name:"zh/classics/koujueyi/042.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>彖曰：「解」，险以动，动而免乎险，解。「解利西南」，往得众也。「其来复吉」，乃得中也。「有攸往，夙吉」，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之时大矣哉！</p><p>象曰：雷雨作，解，君子以赦过宥罪。</p><p>初六，无咎。</p><p>象曰：刚柔之际，义无咎也。</p><p>九二，田获三狐，得黄矢，贞吉。</p><p>象曰：九二「贞吉」，得中道也。</p><p>六三，负且乘，致寇至，贞吝。</p><p>象曰：「负且乘」，亦可丑也。自我致戎，又谁咎也！</p><p>九四，解而拇，朋至斯孚。</p><p>象曰：「解而拇」，未当位也。</p><p>六五，君子维有解，吉。有孚于小人。</p><p>象曰：君子有解，小人退也。</p><p>上六，公用射隼于高墉之上，获之无不利。</p><p>象曰：「公用射隼」，以解悖也。</p><p>解读</p><p>解利西南者，解，缓也，谓难道解释，物情舒缓，故谓「解」也。西南坤位，坤训众也，夫散难释险，利施于众，即所济弘大，故曰「利西南」也。无所往其来复吉者，若难道已散，无难可救，即宜反复守其静默，即合于常理也。「有攸往夙吉」者，夙，早也，速也，若难道方殷，虑其侵伤平人，必须速往救济，以安险俗，故曰「夙吉」。象曰「雷雨作，解」者，雷既发动，雨泽施降，物情舒畅，故是解缓之象也。「君子以赦过宥罪」者，赦，放也；宥，宽也；过谓误犯，罪谓故为，过轻即放舍，罪重即宽宥，如似合死从流，合流从徒，皆是缓其罪刑也。</p><p>「初六无咎」者，难道已散，上有所应，故「无咎」也。</p><p>「九二，田获三狐，得黄矢，贞吉」者，隐伏之物，喻犴猾之人。九二以刚居其位，为君委任，能散险难，能除奸暴之人，如似田猎而获三狐，能持中直之道而令其正，故曰「得黄矢，贞吉」也。</p><p>「六三负且乘，致寇至，贞吝」者，六三位既不正，而以谄媚上附九四，下乘于二，如似担负之人乘君子之乘，即寇盗必见其侵伤，故曰「负且乘，致寇至」。以不正之身，虽幸而免，是正人之所贱，故曰「贞吝」也。</p><p>「九四，解而拇，朋至斯孚」者，拇，足指也；而，汝也。九四位既不正，三亦不正，以相亲比，三附于四，如指附足。然九四本应在初，若与三相附，即失其本应。若四能弃三之拇，即初六之朋与己合信，故曰「朋至斯孚」也。</p><p>六五：君子维有解，吉。「有孚于小人」者，以柔居尊，不自专制，而委九二，任用得人，是有君子之德，而能解释险难，故曰「君子维有解，吉」也。以君子之道而能散难，即小人虽伏暗昧，亦能信服君子，不敢为非，故曰「有孚于小人」也。</p><p>上六：公用射隼于高墉之上，获之，无不利者，公者，臣之极贵者也。上六以阳居极，故称「公」也。居动之上，为解之极，是能去贪暴，除凶悖，故以「射隼」论之。隼者，贪贱之鸟，鹰鹯之属，为六三失位不正。隼之为鸟，宜居山林，而止于人家墉墙之上，即为人所憎，射之克中，故曰「获之，无不利」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
